#define main original_search_main
#include "search.cpp"
#undef main
int main(){for(int i=0;i<N;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i+19<N)a[i].push_back(i+19);}ifstream f(S("rfFile"));if(!f){cerr<<"нет файла "<<S("rfFile")<<"\n";return 2;}Cand c;f>>c.power>>c.heat>>c.cool>>c.cost>>c.av>>c.hs>>c.ex>>c.re>>c.ch>>c.seed;string row;while(f>>row)c.g+=row;if((int)c.g.size()!=N){cerr<<"схема должна быть 19x16\n";return 2;}string base=c.g;for(int i=0;i<N;i++)if(i%19>=15)base[i]='K';for(auto [x,y]:vector<pair<int,int>>{{16,1},{17,2},{16,3}}){int i=y*19+x;base[i]='1';for(int j:a[i])if(!core(base[j]))base[j]='R';}int fi=11*19+17;base[fi]='1';for(int j:a[fi])base[j]='C';for(int dx:{-1,1})for(int dy:{-1,1})base[fi+dx+dy*19]='I';
 int pMin=(int)PI("rfPmin"),pMax=(int)PI("rfPmax"),pFinal=(int)PI("rfPfinal"),exFinal=(int)PI("rfExFinal");double maxFillLim=P("rfFill"),minCool=P("rfMinCool");
 ofstream outcsv("refine-tests.csv");outcsv<<"P,ex,method,fault,maxE,maxV,maxC,maxHull,storedC\n";double bestScore=-1000;for(int pc=pMin;pc<=pMax;pc++)for(int ex=0;ex<2;ex++){Cand z=c;z.g=base;z.ex=ex;int countP=(int)count(z.g.begin(),z.g.end(),'P');for(int i=N-1;i>=0&&countP<pc;i--)if(z.g[i]=='K'){z.g[i]='P';countP++;}int k=(int)count(z.g.begin(),z.g.end(),'K');z.cool=count(z.g.begin(),z.g.end(),'V')*M.vr0*(1+M.ventBoost*(M.bAv+z.av)*k);if(z.cool<minCool)continue;array<int,128>cnt{};for(char v:z.g)cnt[v]++;double raw=0;for(int i=0;i<N;i++)if(int co=core(z.g[i])){int pulse=co==1?1:co==2?4:12,r=0;for(int j:a[i]){pulse+=core(z.g[j]);r+=z.g[j]=='R';}raw+=pulse*M.fuelPow*(1+M.refl*r);}z.power=raw*M.boost(M.fuelHeat-pc*M.hullPer*M.drain);z.cost=PR.fuel(cnt)+PR.upgrades(z.av,z.hs,ex,z.re,0)+PR.parts(cnt);bool ok=true;double maxFill=0;for(int m=0;m<2;m++)for(int fault=0;fault<3;fault++){ostringstream tr;if(!sim(z,m,fault,&tr)){ok=false;continue;}outcsv<<pc<<","<<ex<<","<<tr.str();string vals=tr.str();replace(vals.begin(),vals.end(),',',' ');istringstream v(vals);int mm,ff;double ee;v>>mm>>ff>>ee;maxFill=max(maxFill,ee);}cerr<<"Plating "<<pc<<" Exch "<<ex<<" ok "<<ok<<" заполнение "<<maxFill<<"\n";if(ok&&maxFill<=maxFillLim&&pc==pFinal&&ex==exFinal){bestScore=-z.cost;ofstream out("final.txt");out<<setprecision(12)<<z.power<<" "<<z.heat<<" "<<z.cool<<" "<<z.cost<<" "<<z.av<<" "<<z.hs<<" "<<z.ex<<" "<<z.re<<" "<<z.ch<<" "<<z.seed<<"\n";for(int y=0;y<16;y++)out<<z.g.substr(y*19,19)<<"\n";cerr<<"-> final.txt\n";}}return 0;}
